import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"部分（Section） - October CMS - 3.x","titleTemplate":false,"description":"使用专用 URL 定义网站部分。","frontmatter":{"subtitle":"使用专用 URL 定义网站部分。"},"headers":[{"level":2,"title":"可用属性","slug":"可用属性","link":"#可用属性","children":[]},{"level":2,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]},{"level":2,"title":"更改查找标识符","slug":"更改查找标识符","link":"#更改查找标识符","children":[]},{"level":2,"title":"检查记录是否存在","slug":"检查记录是否存在","link":"#检查记录是否存在","children":[]},{"level":2,"title":"访问条目类型","slug":"访问条目类型","link":"#访问条目类型","children":[]},{"level":2,"title":"使用完整 Slug","slug":"使用完整-slug","link":"#使用完整-slug","children":[]}],"relativePath":"3.x/zh-cn/cms/components/section.md","filePath":"3.x/zh-cn/cms/components/section.md"}'),u={name:"3.x/zh-cn/cms/components/section.md"};function r(k,n,d,g,m,v){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"部分（Section）",-1)),s(e),n[1]||(n[1]=i(`<p><code>section</code> 组件定义了一个带有关联条目的网站部分。该部分将在从后端面板预览条目时使用。</p><h2 id="可用属性"><a href="#可用属性" class="header-anchor">#</a> 可用属性</h2><p>该组件支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td><a href="./../tailor/blueprints.html">条目蓝图</a>的句柄。</td></tr><tr><td><strong>identifier</strong></td><td>使用此标识符键来查找条目，支持的值为 <code>slug</code>、<code>fullslug</code> 或 <code>id</code>。默认值：<code>slug</code></td></tr><tr><td><strong>value</strong></td><td>使用此标识符值来查找条目，可选。留空则使用标识符键作为 URL 参数名称。可以设置为硬编码值或自定义参数，例如：<code>{{ :slug }}</code></td></tr><tr><td><strong>isDefault</strong></td><td>在预览条目时将此设为默认页面。默认值：<code>true</code>。</td></tr></tbody></table></div><h2 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h2><p>以下示例为 <strong>Blog\\Author</strong> 条目创建了一个部分，并使用默认的 <code>:slug</code> <a href="./../themes/pages.html">URL 参数</a>来定位它。通过访问 <code>{{ section.title }}</code> Twig 变量来显示作者名称作为标题。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> section<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>当同一页面上使用多个部分时，可以使用组件别名来分配不同的变量名称以供页面使用。以下组件别名 <strong>author</strong> 使得标题可以通过 <code>{{ author.title }}</code> Twig 变量来访问。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section author</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> author<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="更改查找标识符"><a href="#更改查找标识符" class="header-anchor">#</a> 更改查找标识符</h2><p>默认标识符为 <code>slug</code>，可以通过更改 <code>identifier</code> 属性来修改，例如使用 <code>id</code> 列来定位记录。请注意，页面 URL 也会相应更改为使用 <code>:id</code> 参数名称。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><p>您可以使用 <code>value</code> 属性硬编码标识符查找，例如将其设置为 <strong>7</strong> 将使用静态查找来显示记录。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/ceo</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">7</span>
</code></pre></div><p><code>value</code> 属性也接受外部参数，以下示例使用 <strong>foobar</strong> URL 参数来查找记录。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:foobar</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :foobar }}</span>&quot;</span>
</code></pre></div><div class="custom-block warning"><p>预览链接和使用<a href="./../../element/form/widget-pagefinder.html">页面查找器小部件</a>不支持具有自定义值的标识符。</p></div><h2 id="检查记录是否存在"><a href="#检查记录是否存在" class="header-anchor">#</a> 检查记录是否存在</h2><p>在大多数情况下，当找不到记录时，您需要显示 404 页面。这可以通过使用 <code>{% if %}</code> 语句结合 <code>abort(404)</code> 函数来实现。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> author <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../markup/function/abort.html"><code>abort()</code> Twig 函数</a>用于在未找到记录时显示 404 页面。</p></div><h2 id="访问条目类型"><a href="#访问条目类型" class="header-anchor">#</a> 访问条目类型</h2><p>当使用条目蓝图的<a href="./blueprints.html">内容组</a>功能时，您可以使用 <code>content_group</code> 属性访问组代码。例如，一篇文章可能有 <strong>regular_post</strong> 和 <strong>markdown_post</strong> 内容组，其中内容的处理方式不同。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> post<span class="token punctuation">.</span>content_group <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>markdown_post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as Markdown --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>md <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as HTML --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="使用完整-slug"><a href="#使用完整-slug" class="header-anchor">#</a> 使用完整 Slug</h2><p>如果条目类型为 <code>structure</code>，则它将具有可用的 <strong>fullslug</strong> 属性。要在页面 URL 中使用完整 slug，应将其定义为<a href="./../themes/pages.html">通配符 URL 参数</a>。组件的 <code>identifier</code> 属性应设置为 <strong>fullslug</strong>。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">fullslug</span>&quot;</span>
</code></pre></div><p>作为替代方法，我们建议将 <strong>id</strong> 放在 URL 的末尾来定位记录。这样可以自由移动记录而不会破坏网站中的链接。以下示例展示了如何通过重定向之前使用的 URL 来实现这一点。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> article <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> article<span class="token punctuation">.</span>fullslug <span class="token operator">!=</span> this<span class="token punctuation">.</span>param<span class="token punctuation">.</span>fullslug <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span>this<span class="token operator">|</span>page<span class="token punctuation">(</span><span class="token punctuation">{</span> fullslug<span class="token punctuation">:</span> article<span class="token punctuation">.</span>fullslug <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">301</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- Contents here --&gt;</span>
</code></pre></div></div><div class="custom-block tip"><p><a href="./../../markup/function/redirect.html"><code>redirect()</code> Twig 函数</a>用于在 slug 不匹配时进行永久 301 重定向。<a href="./../../markup/filter/page.html"><code>|page</code> Twig 过滤器</a>提供当前页面并将 <code>fullslug</code> URL 参数重写为正确的匹配值。</p></div>`,30))])}const f=p(u,[["render",r]]);export{w as __pageData,f as default};
